<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';
require __DIR__.'/includes/auth.php';
require_permission('catalog.view');

$pageTitle='Productos y servicios';
$pdo=db();
$q=trim((string)($_GET['q']??''));
$state=(string)($_GET['state']??'all');
$categoryId=max(0,(int)($_GET['category_id']??0));
$usage=(string)($_GET['usage']??'all');
$itemType=(string)($_GET['type']??'all');
$sort=(string)($_GET['sort']??'category');
$perPage=(int)($_GET['per_page']??50);
$perPage=in_array($perPage,[25,50,100,250],true)?$perPage:50;
$page=max(1,(int)($_GET['page']??1));
$categories=$pdo->query('SELECT id,name,is_active FROM service_categories ORDER BY sort_order,name')->fetchAll();

$where=[];$params=[];
if($q!==''){$where[]='(sc.name_es LIKE ? OR sc.name_pt LIKE ? OR sc.name_en LIKE ? OR COALESCE(cat.name,sc.category) LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like,$like);}
if($state==='active')$where[]='sc.is_active=1';elseif($state==='inactive')$where[]='sc.is_active=0';
if(in_array($itemType,['service','product'],true)){$where[]='sc.item_type=?';$params[]=$itemType;}
if($categoryId>0){$where[]='sc.category_id=?';$params[]=$categoryId;}
$usageExpr='(COALESCE(cs.contract_count,0)+COALESCE(qs.quote_count,0))';
$lastExpr="GREATEST(COALESCE(cs.last_used_at,'1000-01-01 00:00:00'),COALESCE(qs.last_used_at,'1000-01-01 00:00:00'))";
if($usage==='recent30')$where[]="$lastExpr >= DATE_SUB(NOW(),INTERVAL 30 DAY)";elseif($usage==='recent90')$where[]="$lastExpr >= DATE_SUB(NOW(),INTERVAL 90 DAY)";elseif($usage==='used')$where[]="$usageExpr > 0";elseif($usage==='never')$where[]="$usageExpr = 0";
$orderBy=match($sort){'name'=>'sc.name_es ASC','recent'=>"$lastExpr DESC,sc.name_es ASC",'usage'=>"$usageExpr DESC,sc.name_es ASC",'status'=>'sc.is_active DESC,sc.name_es ASC',default=>"COALESCE(NULLIF(cat.name,''),NULLIF(sc.category,''),'Sin categoría') ASC,sc.name_es ASC"};
$joins=" LEFT JOIN service_categories cat ON cat.id=sc.category_id
LEFT JOIN (SELECT catalog_service_id,COUNT(*) contract_count,MAX(updated_at) last_used_at FROM client_services WHERE catalog_service_id IS NOT NULL GROUP BY catalog_service_id) cs ON cs.catalog_service_id=sc.id
LEFT JOIN (SELECT qi.catalog_service_id,COUNT(*) quote_count,MAX(q.updated_at) last_used_at FROM quotation_items qi JOIN quotations q ON q.id=qi.quotation_id WHERE qi.catalog_service_id IS NOT NULL GROUP BY qi.catalog_service_id) qs ON qs.catalog_service_id=sc.id";
$whereSql=$where?' WHERE '.implode(' AND ',$where):'';
$countStmt=$pdo->prepare("SELECT COUNT(*) FROM service_catalog sc $joins $whereSql");$countStmt->execute($params);$total=(int)$countStmt->fetchColumn();
$totalPages=max(1,(int)ceil($total/$perPage));if($page>$totalPages)$page=$totalPages;$offset=($page-1)*$perPage;
$sql="SELECT sc.*,COALESCE(cat.name,sc.category) category_name,COALESCE(cs.contract_count,0) contract_count,COALESCE(qs.quote_count,0) quote_count,$usageExpr usage_count,NULLIF($lastExpr,'1000-01-01 00:00:00') last_used_at FROM service_catalog sc $joins $whereSql ORDER BY $orderBy LIMIT $perPage OFFSET $offset";
$stmt=$pdo->prepare($sql);$stmt->execute($params);$services=$stmt->fetchAll();
function catalog_query(array $replace=[]):string{$query=array_merge($_GET,$replace);foreach($query as$k=>$v)if($v===''||$v===null)unset($query[$k]);return'?'.http_build_query($query);} 
require __DIR__.'/includes/header.php';
?>
<section class="panel">
<div class="panel-header"><div><h2>Productos y servicios</h2><span class="table-sub"><?=$total?> ítems encontrados. Todo lo activo aparece al preparar una cotización.</span></div><div class="actions"><a class="btn btn-light" href="quote_catalog.php">RESUMEN</a><a class="btn btn-success" href="service_catalog_export.php?<?=e(http_build_query(array_filter(['q'=>$q,'state'=>$state,'category_id'=>$categoryId,'usage'=>$usage,'sort'=>$sort,'type'=>$itemType],fn($v)=>$v!==''&&$v!==0)))?>">EXPORTAR A EXCEL</a><?php if(has_permission('catalog_categories.view')):?><a class="btn btn-light" href="service_categories.php">CATEGORÍAS</a><?php endif;?><?php if(has_permission('catalog.manage')):?><a class="btn btn-primary" href="service_catalog_form.php">+ PRODUCTO O SERVICIO</a><?php endif;?></div></div>
<div class="panel-body"><form method="get" class="filters-wide"><label>Buscar<input name="q" value="<?=e($q)?>" placeholder="Nombre o categoría"></label><label>Tipo<select name="type"><option value="all" <?=$itemType==='all'?'selected':''?>>Todos</option><option value="service" <?=$itemType==='service'?'selected':''?>>Servicios</option><option value="product" <?=$itemType==='product'?'selected':''?>>Productos</option></select></label><label>Categoría<select name="category_id"><option value="0">Todas</option><?php foreach($categories as$cat):?><option value="<?=(int)$cat['id']?>" <?=$categoryId===(int)$cat['id']?'selected':''?>><?=e($cat['name'])?><?=$cat['is_active']?'':' · Inactiva'?></option><?php endforeach;?></select></label><label>Estado<select name="state"><option value="all" <?=$state==='all'?'selected':''?>>Todos</option><option value="active" <?=$state==='active'?'selected':''?>>Activos</option><option value="inactive" <?=$state==='inactive'?'selected':''?>>Inactivos</option></select></label><label>Uso<select name="usage"><option value="all" <?=$usage==='all'?'selected':''?>>Cualquier uso</option><option value="recent30" <?=$usage==='recent30'?'selected':''?>>Usados últimos 30 días</option><option value="recent90" <?=$usage==='recent90'?'selected':''?>>Usados últimos 90 días</option><option value="used" <?=$usage==='used'?'selected':''?>>Usados alguna vez</option><option value="never" <?=$usage==='never'?'selected':''?>>Nunca usados</option></select></label><label>Orden<select name="sort"><option value="category" <?=$sort==='category'?'selected':''?>>Categoría y nombre</option><option value="name" <?=$sort==='name'?'selected':''?>>Nombre</option><option value="recent" <?=$sort==='recent'?'selected':''?>>Últimos usados</option><option value="usage" <?=$sort==='usage'?'selected':''?>>Más usados</option><option value="status" <?=$sort==='status'?'selected':''?>>Estado</option></select></label><label>Por página<select name="per_page"><option value="25" <?=$perPage===25?'selected':''?>>25</option><option value="50" <?=$perPage===50?'selected':''?>>50</option><option value="100" <?=$perPage===100?'selected':''?>>100</option><option value="250" <?=$perPage===250?'selected':''?>>Todos</option></select></label><button class="btn btn-secondary btn-small">FILTRAR</button></form></div>
<div class="table-wrap"><?php if(!$services):?><div class="empty">No hay productos o servicios que coincidan con los filtros.</div><?php else:?><table class="data-table catalog-list-table"><thead><tr><th>Tipo</th><th>Producto / servicio</th><th>Categoría</th><th>Modalidad</th><th>Precios</th><th>Uso</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($services as$s):?><tr><td><span class="badge <?=$s['item_type']==='product'?'badge-yellow':'badge-blue'?>"><?=$s['item_type']==='product'?'Producto':'Servicio'?></span></td><td class="catalog-name-cell"><strong><?=e($s['name_es'])?></strong><div class="catalog-translations"><span><b>PT:</b> <?=e($s['name_pt']?:'—')?></span><span><b>EN:</b> <?=e($s['name_en']?:'—')?></span></div></td><td><?=e($s['category_name']?:'Sin categoría')?></td><td><?=e(contract_label($s['default_contract_type']))?><?php if($s['default_contract_type']==='custom'&&$s['custom_period_months']):?><span class="table-sub"><?=(int)$s['custom_period_months']?> meses</span><?php endif;?></td><td><div class="price-row" style="margin:0"><span class="price-chip">CLP <?=e(format_money($s['price_clp'],'CLP'))?></span><span class="price-chip">USD <?=e(format_money($s['price_usd'],'USD'))?></span><span class="price-chip">BRL <?=e(format_money($s['price_brl'],'BRL'))?></span></div></td><td class="catalog-use"><strong><?=(int)$s['usage_count']?></strong> usos<span class="table-sub"><?=(int)$s['contract_count']?> servicios de clientes · <?=(int)$s['quote_count']?> cotizaciones</span><span class="table-sub">Último: <?=e($s['last_used_at']?(new DateTimeImmutable($s['last_used_at']))->format('d/m/Y'):'Nunca')?></span></td><td><span class="badge badge-<?=$s['is_active']?'green':'gray'?>"><?=$s['is_active']?'Activo':'Inactivo'?></span></td><td><?php if(has_permission('catalog.manage')):?><div class="icon-actions"><a class="icon-action" href="service_catalog_form.php?id=<?=(int)$s['id']?>" title="Editar producto o servicio"><?=crm_icon('edit')?></a><form method="post" action="service_catalog_toggle.php"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$s['id']?>"><button class="icon-action <?=$s['is_active']?'':'success'?>" title="<?=$s['is_active']?'Desactivar':'Activar'?>" data-confirm="¿Confirmar el cambio de estado?"><?=crm_icon('toggle')?></button></form><form method="post" action="service_catalog_delete.php"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$s['id']?>"><button class="icon-action danger" title="Eliminar definitivamente" data-confirm="¿ELIMINAR definitivamente este producto/servicio del catálogo? Las cotizaciones históricas conservarán sus valores."><?=crm_icon('trash')?></button></form></div><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php endif;?></div>
<?php if($totalPages>1):?><nav class="pagination"><?php if($page>1):?><a href="<?=e(catalog_query(['page'=>$page-1]))?>">‹</a><?php endif;?><?php for($i=max(1,$page-2);$i<=min($totalPages,$page+2);$i++):?><?=$i===$page?'<span class="current">'.$i.'</span>':'<a href="'.e(catalog_query(['page'=>$i])).'">'.$i.'</a>'?><?php endfor;?><?php if($page<$totalPages):?><a href="<?=e(catalog_query(['page'=>$page+1]))?>">›</a><?php endif;?></nav><?php endif;?></section>
<?php require __DIR__.'/includes/footer.php';?>
